def E(x): return html.escape(str(x if x is not None else ''))
def country_of(n):
    # Country is derived only from the normalized international calling code.
    # Never use an old range label to decide country.
    d=re.sub(r'\D','',str(n or ''))
    if d.startswith('00'): d=d[2:]
    if d.startswith('212'): return 'Morocco','212'
    if d.startswith('216'): return 'Tunisia','216'
    if d.startswith('62'): return 'Indonesia','62'
    for code,name in sorted(COUNTRIES.items(),key=lambda z:(-len(z[0]),z[0])):
        if d.startswith(code): return name,code
    return 'Other',''

def repair_normalized_numbers(c):
    """Canonicalize legacy numbers, remove duplicate rows, and repair country metadata."""
    rows=c.execute('SELECT * FROM numbers ORDER BY id').fetchall()
    groups={}
    for n in rows:
        canonical=normalize(n['value'])
        if canonical: groups.setdefault(canonical,[]).append(n)
    for canonical,items in groups.items():
        keep=items[0]
        for dup in items[1:]:
            c.execute('UPDATE allocations SET number_id=? WHERE number_id=?',(keep['id'],dup['id']))
            c.execute('DELETE FROM numbers WHERE id=?',(dup['id'],))
        country,code=country_of(canonical)
        c.execute('UPDATE numbers SET value=?,country=?,country_code=? WHERE id=?',(canonical,country,code,keep['id']))

def ensure_number_unique_index(c):
    '''Guarantee one canonical number row per E.164 value.'''
    repair_normalized_numbers(c)
    try:
        c.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_numbers_value ON numbers(value)')
        c.commit()
    except sqlite3.IntegrityError:
        repair_normalized_numbers(c)
        c.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_numbers_value ON numbers(value)')
        c.commit()

def repair_mixed_ranges(c):
    '''Strictly enforce: one active range = one detected international country code.'''
    ranges=c.execute('SELECT * FROM ranges WHERE active=1 ORDER BY id').fetchall()
    for r in ranges:
        nums=c.execute('SELECT * FROM numbers WHERE range_id=? AND active=1 ORDER BY id',(r['id'],)).fetchall()
        groups={}
        for n in nums:
            canonical=normalize(n['value'])
            country,code=country_of(canonical)
            if not canonical or not code:
                # Unknown/invalid international prefix never gets silently assigned to a named country.
                continue
            c.execute('UPDATE numbers SET value=?,country=?,country_code=? WHERE id=?',(canonical,country,code,n['id']))
            groups.setdefault(code,[]).append((n,country,code,canonical))
        if not groups:
            continue

        def unique_country_name(country,current_id):
            base=country or 'Other'; name=base; i=2
            while c.execute('SELECT 1 FROM ranges WHERE name=? AND id<>?',(name,current_id)).fetchone():
                name=f'{base} {i}'; i+=1
            return name

        # Keep the existing range for the first group, but rename it from the old label
        # to the actual country detected from its numbers. Every other country gets its
        # own range. This prevents Morocco/Tunisia (or any other countries) from mixing.
        ordered=sorted(groups.items(), key=lambda kv: min(int(x[0]['id']) for x in kv[1]))
        primary_code,primary_items=ordered[0]
        primary_country=primary_items[0][1]
        old_name=(r['name'] or '').strip()
        if old_name.lower()==primary_country.lower() and (r['country_code'] or '')==primary_code:
            primary_name=old_name
        else:
            primary_name=unique_country_name(primary_country,r['id'])
        c.execute('UPDATE ranges SET name=?,country=?,country_code=? WHERE id=?',(primary_name,primary_country,primary_code,r['id']))

        for code,items in ordered[1:]:
            country=items[0][1]
            name=unique_country_name(country,r['id'])
            c.execute('INSERT INTO ranges(name,country,country_code,rate,active,created_at) VALUES(?,?,?,?,?,?)',(name,country,code,r['rate'],1,now()))
            target_id=c.execute('SELECT last_insert_rowid() id').fetchone()['id']
            for n,cn,ccode,canonical in items:
                c.execute('UPDATE numbers SET range_id=?,value=?,country=?,country_code=? WHERE id=?',(target_id,canonical,cn,ccode,n['id']))

    # Final invariant check: no active range may contain two different country codes.
    bad=c.execute('''SELECT range_id,COUNT(DISTINCT country_code) cnt FROM numbers
                     WHERE active=1 AND range_id IS NOT NULL GROUP BY range_id HAVING cnt>1''').fetchall()
    if bad:
        # Run one more deterministic pass if a legacy database had unusual rows.
        for x in bad:
            r=c.execute('SELECT * FROM ranges WHERE id=?',(x['range_id'],)).fetchone()
            if r:
                nums=c.execute('SELECT * FROM numbers WHERE range_id=? AND active=1 ORDER BY id',(r['id'],)).fetchall()
                for n in nums:
                    canonical=normalize(n['value']); country,code=country_of(canonical)
                    c.execute('UPDATE numbers SET value=?,country=?,country_code=? WHERE id=?',(canonical,country,code,n['id']))
    c.commit()

def normalize(x):
    s=str(x or '').strip()
    d=re.sub(r'\D','',s)
    if d.startswith('00'): d=d[2:]
    return ('+'+d) if d else ''

