class H(BaseHTTPRequestHandler):
    server_version='BilloPython/3.0'
    def log_message(self,*a): pass
    def cookies(self):
        out={}
        for p in self.headers.get('Cookie','').split(';'):
            if '=' in p:
                k,v=p.strip().split('=',1);out[k]=v
        return out
    def body(self):
        n=int(self.headers.get('Content-Length','0') or 0);raw=self.rfile.read(n);ct=self.headers.get('Content-Type','')
        if 'multipart/form-data' in ct:return parse_multipart(raw,ct.split('boundary=',1)[-1].strip().strip('"'))
        q=parse_qs(raw.decode('utf-8','replace'),keep_blank_values=True)
        return {k:(','.join(v) if k in ('members','number_ids') else v[-1]) for k,v in q.items()}
    def send(self,status,data,ctype='text/html; charset=utf-8',cookie=None):
        if isinstance(data,str):data=data.encode()
        self.send_response(status);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(data)));self.send_header('Cache-Control','no-store')
        if cookie:self.send_header('Set-Cookie',cookie)
        self.end_headers();self.wfile.write(data)
    def redirect(self,path,cookie=None):
        self.send_response(302);self.send_header('Location',path);self.send_header('Cache-Control','no-store')
        if cookie:self.send_header('Set-Cookie',cookie)
        self.end_headers()
    def okjson(self,obj,status=200):self.send(status,json.dumps(obj).encode(),'application/json; charset=utf-8')
    def current(self,c):
        t=self.cookies().get('billo_session')
        if not t:return None
        r=c.execute('SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND u.active=1',(t,)).fetchone()
        if r:c.execute('UPDATE sessions SET last_seen=? WHERE token=?',(now(),t));c.commit()
        return r
    def require(self,c,roles=None):
        u=self.current(c)
        if not u:return None
        return False if roles and u['role'] not in roles else u
    def route(self,method):
        p=urlparse(self.path);path=p.path;q=parse_qs(p.query);c=connect();u=None
        try:
            repair_normalized_numbers(c)
            ensure_number_unique_index(c)
            repair_mixed_ranges(c)
            if path=='/login':return self.login(c,method)
            if path=='/logout':return self.logout(c)
            if path=='/api/health':return self.okjson({'status':'ok','service':'Billo SMS','time':now()})
            if path.startswith('/assets/'):
                return self.asset(path[8:])
            if path=='/api/sms/incoming':return self.incoming(c,method,q)
            u=self.require(c)
            if u is None:return self.redirect('/login')
            if u is False:return self.send(403,page('403','<div class="panel">Not authorized.</div>',u))
            if path=='/':return self.dashboard(c,u)
            if path=='/users':return self.users(c,u,method,q)
            if path=='/ranges':return self.ranges(c,u,method,q)
            if path=='/ranges/view':return self.range_view(c,u,q)
            if path=='/numbers':return self.numbers(c,u,q)
            if path=='/numbers/allocate':return self.allocate(c,u,method)
            if path=='/numbers/unallocate':return self.unallocate(c,u,method)
            if path=='/import':return self.import_numbers(c,u,method)
            if path=='/api-management':return self.api_management(c,u,method,q)
            if path=='/cdr':return self.cdr(c,u,q)
            if path=='/stats':return self.stats(c,u,q)
            if path=='/rates':return self.rates(c,u)
            if path=='/payments':return self.payments(c,u)
            if path=='/manager-payments':return self.redirect('/payments')
            if path=='/support':return self.support(c,u,method)
            if path.startswith('/support/'):
                z=path.strip('/').split('/');gid=int(z[1]);return self.chat_send(c,u,gid,method) if len(z)>2 and z[2]=='send' else self.chat(c,u,gid)
            if path=='/settings':return self.settings(c,u,method)
            if path=='/developer':return self.developer(c,u)
            if path=='/default-partner':return self.redirect('/developer')
            return self.send(404,page('404','<div class="panel">Page not found.</div>',u))
        except Exception:
            try:c.rollback()
            except:pass
            return self.send(500,page('500','<div class="panel"><h2>Internal Error</h2><p>The request could not be completed safely.</p></div>',u))
        finally:c.close()
    def do_GET(self):self.route('GET')
    def do_POST(self):self.route('POST')

    def asset(self,name):
        safe=Path(name).name
        allowed={'billo_loop.wav'}
        if safe not in allowed:return self.send(404,b'Not found','text/plain; charset=utf-8')
        p=ASSET_DIR/safe
        if not p.exists():return self.send(404,b'Not found','text/plain; charset=utf-8')
        return self.send(200,p.read_bytes(),'audio/wav')

    def login(self,c,method):
        if method=='GET':
            a=secrets.randbelow(9)+1;b=secrets.randbelow(9)+1;t=secrets.token_urlsafe(24);c.execute('INSERT INTO sessions(token,user_id,captcha_answer,captcha_a,captcha_b,created_at,last_seen) VALUES(?,?,?,?,?,?,?)',(t,None,a+b,a,b,now(),now()));c.commit()
            body='<div class="login-page"><div class="login-brand"><img src="data:image/png;base64,'+LOGO_B64+'"><div><b>Billo <span>SMS</span></b><small>International Messaging Services</small></div></div><div class="login-title">Accounts are free and<br>always will be.</div><div class="login-card"><h2>Welcome back!</h2><p>Please sign in to continue.</p><form method="post"><label>Username</label><input class="input" name="username" placeholder="Enter Your Username" required><label>Password</label><input class="input" type="password" name="password" placeholder="Enter Your Password" required><label>What is '+str(a)+' + '+str(b)+' = ? :</label><input class="input" name="captcha" placeholder="Answer" inputmode="numeric" required><input type="hidden" name="cap_token" value="'+t+'"><button class="btn">Sign In</button></form></div></div>'
            return self.send(200,page('Login',body),cookie='billo_cap='+t+'; Path=/; HttpOnly; SameSite=Lax')
        f=self.body();t=f.get('cap_token') or self.cookies().get('billo_cap');r=c.execute('SELECT * FROM sessions WHERE token=? AND user_id IS NULL',(t,)).fetchone();valid=bool(r and str(f.get('captcha','')).isdigit() and int(f['captcha'])==r['captcha_answer']);username=f.get('username','').strip();u=c.execute('SELECT * FROM users WHERE username=? AND active=1',(username,)).fetchone()
        key=username.lower() or 'unknown'; now_ts=datetime.now(timezone.utc).timestamp(); fails=[x for x in LOGIN_FAILS.get(key,[]) if now_ts-x<600]; LOGIN_FAILS[key]=fails
        if len(fails)>=8:return self.redirect('/login')
        if not valid or not u or not verify_password(f.get('password',''),u['password_hash']):
            LOGIN_FAILS.setdefault(key,[]).append(now_ts)
            if r:c.execute('DELETE FROM sessions WHERE token=?',(t,));c.commit()
            return self.redirect('/login')
        LOGIN_FAILS.pop(key,None)
        nt=secrets.token_urlsafe(40);c.execute('DELETE FROM sessions WHERE token=?',(t,));c.execute('INSERT INTO sessions(token,user_id,created_at,last_seen) VALUES(?,?,?,?)',(nt,u['id'],now(),now()));audit(c,u['id'],'LOGIN','Successful login');c.commit();return self.redirect('/',f'billo_session={nt}; Path=/; HttpOnly; SameSite=Lax')
    def logout(self,c):
        t=self.cookies().get('billo_session');c.execute('DELETE FROM sessions WHERE token=?',(t,));c.commit();return self.redirect('/login','billo_session=x; Max-Age=0; Path=/; HttpOnly')

    def scope_user_ids(self,c,u):
        if u['role']=='OWNER':return None
        if u['role']=='CLIENT':return [u['id']]
        if u['role']=='AGENT':return [u['id']]+[x['id'] for x in c.execute('SELECT id FROM users WHERE parent_id=?',(u['id'],)).fetchall()]
        return [u['id']]+[x['id'] for x in c.execute('SELECT id FROM users WHERE parent_id=? OR parent_id IN (SELECT id FROM users WHERE parent_id=?)',(u['id'],u['id'])).fetchall()]
