        body=f"""{notice}<div class="panel" id="change-ui"><h2>Change UI</h2><div class="theme-card"><form method="post"><input type="hidden" name="action" value="theme"><label>Interface Theme</label><select class="input" name="theme"><option {'selected' if current_theme=='Billo Original' else ''}>Billo Original</option><option {'selected' if current_theme=='New UI' else ''}>New UI</option></select><button class="btn bluebtn">Apply UI</button></form></div></div><div class="panel"><h2>Background Music</h2><p class="small">صرف نرم background music چلتا ہے۔ کوئی click/tap sound effect نہیں ہے۔</p><form method="post"><input type="hidden" name="action" value="music"><label><input type="checkbox" name="music_enabled" value="on" {music_checked}> Background Music ON</label><label>Volume</label><input class="input" type="number" name="music_volume" min="0" max="1" step="0.01" value="{volume}"><button class="btn bluebtn">Save Sound Settings</button></form></div><div class="panel"><h2>My Profile</h2><form method="post"><input type="hidden" name="action" value="profile"><div class="row"><div><label>Username</label><input class="input" value="{E(u['username'])}" readonly></div><div><label>Role</label><input class="input" value="{E(u['role'])}" readonly></div><div><label>Full Name</label><input class="input" name="full_name" value="{E(u['full_name'])}"></div><div><label>Email</label><input class="input" name="email" value="{E(u['email'])}"></div><div><label>WhatsApp</label><input class="input" name="whatsapp" value="{E(u['whatsapp'])}"></div><div><label>Telegram</label><input class="input" name="telegram" value="{E(u['telegram'])}"></div></div><button class="btn bluebtn">Save Profile</button></form></div><div class="panel"><h2>Profile Photo</h2><div style="display:flex;align-items:center;gap:15px;flex-wrap:wrap">{preview}<form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="photo"><input class="input" type="file" name="photo" accept="image/*,.heic,.heif,.avif,.webp" capture="environment" required><button class="btn bluebtn">Upload Photo</button></form></div></div><div class="panel"><h2>Change Password</h2><form method="post"><input type="hidden" name="action" value="password"><label>Current Password</label><input class="input" type="password" name="current_password" required><label>New Password</label><input class="input" type="password" name="new_password" required><label>Confirm New Password</label><input class="input" type="password" name="confirm_password" required><button class="btn bluebtn">Change Password</button></form></div>"""
