def parse_multipart(raw,boundary):
    out={}; sep=b'--'+boundary.encode()
    for part in raw.split(sep)[1:]:
        if part.startswith(b'--'): break
        if part.startswith(b'\r\n'): part=part[2:]
        if b'\r\n\r\n' not in part: continue
        h,d=part.split(b'\r\n\r\n',1)
        if d.endswith(b'\r\n'): d=d[:-2]
        hs=h.decode('utf-8','replace'); m=re.search(r'name="([^"]+)"',hs); fn=re.search(r'filename="([^"]*)"',hs); ctm=re.search(r'Content-Type:\s*([^\r\n]+)',hs,re.I)
        if not m: continue
        name=m.group(1)
        if fn and fn.group(1):
            out['file_name']=fn.group(1); out['file_content']=d.decode('utf-8','replace'); out['file_b64']=base64.b64encode(d).decode(); out['file_type']=(ctm.group(1).strip() if ctm else '')
            if name=='photo': out['photo_b64']=out['file_b64']; out['photo_type']=out['file_type']
        else: out[name]=d.decode('utf-8','replace')
    return out


